 </div>
</template>
<script setup lang="ts">
import{computed,onMounted,reactive,ref}from'vue';import{useRoute,useRouter}from'vue-router';import{ElMessage}from'element-plus';import{stallApi}from'@/api/merchant';import{useUserStore}from'@/stores/user';
const route=useRoute(),router=useRouter(),user=useUserStore(),loading=ref(false),saving=ref(false),meta=reactive<any>({}),form=reactive<any>({});const canEdit=computed(()=>user.user?.roles?.some(r=>['SUPER_ADMIN','SYSTEM_ADMIN'].includes(r)));const defaults={cableQuantity:0,cableModel:'',loadPowerKw:null,meterLocation:'',waterSupply:false,waterMeterCaliber:'',waterMeterLocation:'',drainageAvailable:false,drainagePipeCaliber:'',drainagePipelineNo:'',exhaustDuctAvailable:false,exhaustDuctNo:'',freshAirDuctAvailable:false,freshAirDuctNo:'',airConditionerQuantity:0,fanCoilQuantity:0,hangingCabinetQuantity:0,airOutletQuantity:0,airConditionerModel:'',gasConditionAvailable:false,gasConnected:false,gasType:'',gasPipeQuantity:0,gasPipeCaliber:'',gasPipelineNo:'',gasInterfaceLocation:'',gasMeterNo:'',gasMeterModel:'',gasMeterLocation:'',designGasFlow:null,designGasLoadKw:null,gasValveNo:'',gasAlarm:false,gasAlarmQuantity:0,autoShutoffValve:false,gasAccepted:false,gasAcceptanceDate:'',gasAcceptanceOrg:'',remark:''};
async function load(){loading.value=true;try{const r:any=await stallApi.getEngineering(Number(route.params.id));Object.assign(meta,r);Object.assign(form,defaults,r.profile||{})}finally{loading.value=false}}async function save(){saving.value=true;try{await stallApi.saveEngineering(Number(route.params.id),form);ElMessage.success('铺位工程资料已保存');await load()}finally{saving.value=false}}onMounted(load)
</script>
<style scoped>.subtitle{color:#909399;font-size:13px;margin-top:5px}.notice{margin-bottom:14px}.el-card{margin-bottom:14px}.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:0 16px}.grid .wide{grid-column:span 2}.grid :deep(.el-input-number),.grid :deep(.el-select),.grid :deep(.el-date-editor){width:100%}.bottom-save{text-align:center;padding:8px 0 24px}.bottom-save .el-button{min-width:220px}@media(max-width:768px){.page-header{align-items:flex-start}.grid{grid-template-columns:1fr}.grid .wide{grid-column:auto}.el-card{border-radius:10px}}</style>
